/// <summary>
/// Kurt Scerri - 03/03/2021
/// Replication of Microsoft class <c>BankPaymAdviceVendControllerV2</c> due to internal class declarations
/// </summary>
public class METBankPaymAdviceVendControllerV2 extends SrsPrintMgmtController
{
    private METBankPaymAdviceDefaultParameters defaultParameters;
    private readonly Map vendorPrintMgmtSettingsValidation = new Map(Types::Int64, Types::Enum);

}

Method.Source:
    protected void runPrintMgmt()
    {
        SRSPrintDestinationSettings printSettings;
        METBankPaymAdviceContract contract;
        List paymentLines;

        METBankPaymAdvicePrintMgmtReportFormatSetup::setDefaultFormat(PrintMgmtDocumentType::VendPaymAdvice);

        if (defaultParameters != null)
        {
            printSettings = defaultParameters.printSettings;
            contract = defaultParameters.BankPaymAdviceContract;
            paymentLines = defaultParameters.paymentList;

            this.parmReportContract().parmRdpContract(contract);
        }
        else
        {
            printSettings = this.getDataContractObject(identifierStr(SRSPrintDestinationSettings)) as SRSPrintDestinationSettings;
            contract = this.parmReportContract().parmRdpContract() as METBankPaymAdviceContract;
            paymentLines = this.getPaymentLines(contract);
        }

        NoYes shouldDefaultFromPrintMgmt = contract.parmShouldDefaultFromPrintMgmt();

        ListEnumerator paymentLineEnumerator = paymentLines.getEnumerator();
        LedgerJournalTrans ledgerJournalTrans, ledgerJournalTransGroupBy;

        while (paymentLineEnumerator.moveNext() && !this.parmCancelRun())
        {
            // Bug 71205: MET Payment advice report printed for each individual payment journal line
            ledgerJournalTransGroupBy.data(paymentLineEnumerator.current());
            //ledgerJournalTrans.data(paymentLineEnumerator.current());
            DimensionAttributeValueCombination dimensionAttributeValueCombination;

            // as ledgerJournalTransGroupBy is grouped by payment reference we need to reselect the first payment journal line with matching criteria
            // further down the logic will apply for that 1st payment line vendor and company which should not be an issue in PROD as global vendor details are copied across all LE's

            select firstonly ledgerJournalTrans
                 exists join dimensionAttributeValueCombination
                       where dimensionAttributeValueCombination.RecId == ledgerJournalTrans.LedgerDimension
                          && dimensionAttributeValueCombination.DisplayValue == contract.parmAccountNum()
                          && ledgerJournalTrans.JournalNum == ledgerJournalTransGroupBy.JournalNum
                          && ledgerJournalTrans.PaymReference == ledgerJournalTransGroupBy.PaymReference;
            

            VendTable vendTable = VendTable::findByCompany(ledgerJournalTrans.Company, contract.parmAccountNum());

            //Code added for bug 87848
            /*
            if (vendTable.RecId == 0)
            {
            warning(strFmt("@CashManagement:BankPaymAdviceReportNotAssociatedWithAccountWarning", ledgerJournalTrans.Voucher, "@SYS8079"));

            continue;
            }*/
            if(contract.parmAccountNum())
            {
                vendTable = VendTable::findByCompany(ledgerJournalTrans.Company, contract.parmAccountNum());

                this.updateContractForLine(contract, ledgerJournalTrans, vendTable);

                this.setPrintMgmtReportRun(vendTable, printSettings, shouldDefaultFromPrintMgmt);

                if (this.checkReportRunSettings(vendTable))
                {
                    this.outputReports();
                }
            }
            else
            {
                VendAccount  vendAcc;

                while select ledgerJournalTrans where ledgerJournalTrans.JournalNum == ledgerJournalTransGroupBy.JournalNum
                {
                    vendAcc = LedgerDynamicAccountHelper::getAccountNumberFromDynamicAccount(ledgerJournalTrans.LedgerDimension);
                    vendTable = VendTable::findByCompany(ledgerJournalTrans.Company, vendAcc);

                    //for venpplus journal condion for 87779.
                    if(LedgerJournalTable::find(ledgerJournalTrans.JournalNum).JournalName == 'VenPPlus'
                        && ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::Confirmed)
                    {
                        this.updateContractForLine(contract, ledgerJournalTrans, vendTable);

                        this.setPrintMgmtReportRun(vendTable, printSettings, shouldDefaultFromPrintMgmt);

                        if (this.checkReportRunSettings(vendTable))
                        {
                            this.outputReports();
                        }
                    }//87779
                    else if(LedgerJournalTable::find(ledgerJournalTrans.JournalNum).JournalName != 'VenPPlus'
                        && ledgerJournalTrans.PaymentStatus == CustVendPaymStatus::Sent)
                    {
                        this.updateContractForLine(contract, ledgerJournalTrans, vendTable);

                        this.setPrintMgmtReportRun(vendTable, printSettings, shouldDefaultFromPrintMgmt);

                        if (this.checkReportRunSettings(vendTable))
                        {
                            this.outputReports();
                        }
                    }

                }
            }
            //87848

        }
    }

private List getPaymentLines(METBankPaymAdviceContract _contract)
{
    METBankPaymAdvicePaymentLineGenerator paymentLineGenerator = METBankPaymAdvicePaymentLineGenerator::construct();

    return paymentLineGenerator.getPaymentLines(_contract);
}

private void setPrintMgmtReportRun(VendTable _vendTable, SRSPrintDestinationSettings _printSettings, NoYes _shouldDefaultFromPrintMgmt)
{
    VendLanguageId vendorLanguage = this.getVendorLanguage(_vendTable);

    changecompany (_vendTable.DataAreaId)
    {
        this.initPrintMgmtReportRun();

        if (_shouldDefaultFromPrintMgmt)
        {
            this.defaultFromPrintMgmt(_vendTable, vendorLanguage);
        }
        else
        {
            PrintMgmtPrintSettingDetail printSettingDetail = this.initPrintSettingDetailFromPrintSettings(_printSettings);
            printMgmtReportRun.loadSettingDetail(printSettingDetail);
        }

        this.setLanguage(vendorLanguage);
    }

    this.parmReportContract().parmPrintSettings().parmSRSPrintArchiveContract().parmExecutionID('');
}

protected void initPrintMgmtReportRun()
{
    printMgmtReportRun = PrintMgmtReportRun::construct(
            PrintMgmtHierarchyType::Purch,
            PrintMgmtNodeType::VendTable,
            PrintMgmtDocumentType::VendPaymAdvice);

    printMgmtReportRun.parmReportRunController(this);

    super();
}

private PrintMgmtPrintSettingDetail initPrintSettingDetailFromPrintSettings(SRSPrintDestinationSettings _printSettings)
{
    const str NoCountryRegionId = '';

    PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findByTypeWithSystem(
            PrintMgmtDocumentType::VendPaymAdvice,
            this.getReportName(),
            NoCountryRegionId);

    PrintMgmtPrintSettingDetail printSettingDetail = new PrintMgmtPrintSettingDetail();
    printSettingDetail.parmReportFormatName(printMgmtReportFormat.Name);
    printSettingDetail.parmSSRS(printMgmtReportFormat.SSRS);
    printSettingDetail.parmType(PrintMgmtDocInstanceType::Original);
    printSettingDetail.parmInstanceName(enum2str(PrintMgmtDocInstanceType::Original));
    printSettingDetail.parmNumberOfCopies(1);
    printSettingDetail.parmPrintJobSettings(_printSettings);

    return printSettingDetail;
}

private VendLanguageId getVendorLanguage(VendTable _vendTable)
{
    VendLanguageId vendLanguageId = _vendTable.languageId();
    return vendLanguageId ? vendLanguageId : CompanyInfo::languageId();
}

private boolean checkReportRunSettings(VendTable _vendTable)
{
    boolean arePrintMgmtSettingsValid = true;

    if (!printMgmtReportRun.more())
    {
        if (vendorPrintMgmtSettingsValidation.exists(_vendTable.RecId))
        {
            arePrintMgmtSettingsValid = vendorPrintMgmtSettingsValidation.lookup(_vendTable.RecId);
        }
        else
        {
            setPrefix(strFmt("@CashManagement:BankPaymAdviceReportVendPrefix", _vendTable.name()));

            arePrintMgmtSettingsValid = checkFailed("@CashManagement:BankPaymAdviceReportVendPrintSettingsError");

            vendorPrintMgmtSettingsValidation.insert(_vendTable.RecId, arePrintMgmtSettingsValid);
        }
    }

    return arePrintMgmtSettingsValid;
}

public boolean showQueryValues(str parameterName)
{
    return false;
}

protected str getReportName()
{
    return ssrsReportStr(METBankPaymAdviceVendV2, Report);
}

internal static void main(Args _args)
{
    METBankPaymAdviceVendControllerV2 controller = new METBankPaymAdviceVendControllerV2();
    boolean shouldShowDialog = true;

    if (_args && _args.parmObject() is BankPaymAdviceDefaultParameters)
    {
        shouldShowDialog = false;
        controller.defaultParameters = _args.parmObject();
    }

    controller.parmReportName(controller.getReportName());
    controller.parmArgs(_args);

    // SysLastValue should not be used when the controller can run with or without a dialog since the last saved value will override the input from this execution.
    controller.parmShowDialog(shouldShowDialog);
    controller.parmLoadFromSysLastValue(false);

    controller.startOperation();
}
